def fib(n: int) -> int:
    """
    Compute the nth Fibonacci number using the fast doubling method.
    Time complexity: O(log n)
    Space complexity: O(log n)
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 0
    if n == 1:
        return 1

    # Helper function to compute (F(n), F(n+1))
    def fib_pair(n: int) -> tuple[int, int]:
        if n == 0:
            return (0, 1)
        if n == 1:
            return (1, 1)

        a, b = fib_pair(n >> 1)
        c = a * b
        d = a + b
        # F(2k) = c, F(2k+1) = d
        return (c, d)

    n = n & ((1 << 30) - 1)  # Ensure n fits in 30 bits (fast for n=300)
    _, last = fib_pair(n)
    return last
