def spiral(m: list[list[int]]) -> list[int]:
    if not m or not m[0]:
        return []

    rows = len(m)
    cols = len(m[0])
    result = []
    top, bottom = 0, rows - 1
    left, right = 0, cols - 1

    while True:
        # Traverse from left to right
        for col in range(left, right + 1):
            result.append(m[top][col])
        top += 1

        # Traverse from top to bottom
        for row in range(top, bottom + 1):
            result.append(m[row][right])
        right -= 1

        # Traverse from right to left (if not at top)
        if top <= bottom:
            for col in range(right, left - 1, -1):
                result.append(m[bottom][col])
            bottom -= 1

        # Traverse from bottom to top (if not at right)
        if left <= right:
            for row in range(bottom, top - 1, -1):
                result.append(m[row][left])
            left += 1

        # Check if we have completed the spiral
        if top > bottom or right < left:
            break

    return result
